using namespace dome;
AffineTransform matrix(const RigMatrix&a){std::array<double,16>m;std::copy(a.begin(),a.end(),m.begin());return AffineTransform(m);}
int main(int argc,char**argv)try{
 const auto*full_path=std::getenv("DOME_HEAT_NATIVE_EXPECTED");if(!full_path)throw std::invalid_argument("Read-only post-solve expected field required");const auto full=Scene::load(full_path);
 if(argc==3&&std::string_view(argv[1])=="--ui-fixture"){const auto*input=std::getenv("DOME_HEAT_NATIVE_INPUT");if(!input)throw std::invalid_argument("Authentic unweighted native input required");auto scene=Scene::load(input);uint64_t selected=0;for(const auto&o:scene.objects()){const auto&f=full.object(o.id);if(!o.painted||!f.deformation||!f.deformation->skin||!f.deformation->humanoid||!o.deformation||o.deformation->skeleton||!o.deformation->morphs||o.deformation->morphs->targets.empty())continue;const auto head=f.deformation->humanoid->joints.at("head");bool yes=true;for(const auto&row:f.deformation->skin->vertices)yes&=row.size()==1&&row[0].joint==head&&row[0].weight==1;if(yes){selected=o.id;break;}}if(!selected)throw std::runtime_error("Actual post-solve head field with current unskinned native morph target required");scene.select(selected);auto d=*scene.active().deformation;d.morph_weights.assign(d.morphs->targets.size(),0);d.morph_weights[0]=.25f;scene.set_deformation(selected,d);scene.save(argv[2]);return 0;}
 if(argc==4&&std::string_view(argv[1])=="--inspect"){auto scene=Scene::load(argv[2]);const auto before=Scene::load(argv[3]);const auto&o=scene.active();const auto&m=o.painted->mesh();const bool skin=o.deformation&&o.deformation->skin;bool matches=false,retained=false;double foreign=0,error=0;if(skin){const auto&d=*o.deformation;const auto head=d.humanoid->joints.at("head");for(const auto&row:d.skin->vertices)for(auto x:row)if(x.joint!=head)foreign=std::max(foreign,double(x.weight));auto expected=*full.object(o.id).deformation;expected.morph_weights=before.object(o.id).deformation->morph_weights;matches=expected.encode(m)==d.encode(m);auto restored=scene;restored.object(o.id).deformation=before.object(o.id).deformation;restored.object(o.id).rig_source=before.object(o.id).rig_source;retained=restored.encode()==before.encode();auto moved=d;if(moved.pose.empty())for(const auto&b:moved.skeleton->bones)moved.pose.push_back(b.rest);if(moved.pose.at(head).full_local_matrix)throw std::runtime_error("GUI head fixture needs genuine editable TRS pose");const auto prior_pose=moved.pose;const auto matrices=d.skeleton->world(prior_pose);const int parent=d.skeleton->bones.at(head).parent;const auto parent_world=parent>=0?matrix(matrices.at(size_t(parent))):d.skeleton->space_matrix?matrix(*d.skeleton->space_matrix):AffineTransform{};auto delta=parent_world.direction({0,0,.05f});moved.pose[head].translation.z+=.05f;const auto base=d.preview(m),posed=moved.preview(m);const auto world=scene.world_matrix(o.id);delta=world.direction(delta);for(size_t i=0;i<m.positions.size();++i){auto p=base.positions[i],q=posed.positions[i];auto wanted=world.point({p.x,p.y,p.z}),actual=world.point({q.x,q.y,q.z});for(size_t k=0;k<3;++k)wanted[k]+=delta[k];error=std::max(error,std::hypot(actual[0]-wanted[0],actual[1]-wanted[1],actual[2]-wanted[2]));}}
 std::cout<<nlohmann::json{{"skinned",skin},{"foreign_weight",foreign},{"max_pose_m",error},{"field_matches",matches},{"retained_exact",retained},{"scene",scene.encode()}}.dump()<<std::endl;return 0;}
 return 2;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
